from pycardano import TransactionInput, Address, UTxO, PlutusV2Script


def get_ref_utxo_from_input_id(address: Address, tx_hash: str, index: int, context):
    tx_in = TransactionInput.from_primitive([tx_hash, index])
    utxos = context.utxos(address)
    for utxo in utxos:
        utxo: UTxO
        if (
            utxo.input.transaction_id == tx_in.transaction_id
            and utxo.input.index == tx_in.index
        ):
            return utxo
    raise ValueError(f"UTxO with input {tx_in} not found at address {address}")


